import type { BankQuestion } from "@/lib/bank";

/** Marketing & Sales Management (Management & Commerce): 116 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"mgmt-marketing-1","question":"The founder of a kitchen-appliance start-up says: \"Our mixer has the most powerful motor in the market. If we keep improving the engineering, customers will find us.\" Which marketing orientation does this reflect?","options":["Production concept","Product concept","Selling concept","Marketing concept"],"answer":1,"explanation":"The product concept assumes customers favour the best quality or most features and that improving the product is enough. The production concept focuses on cheap and widely available goods, the selling concept on pushing what is made, and the marketing concept starts from customer needs.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-2","question":"A retailer buys a shampoo bottle for ₹80 and sells it for ₹100. What is the retailer's margin on the selling price?","options":["80%","25%","20%","16%"],"answer":2,"explanation":"Margin on selling price = (100 − 80) / 100 = 20%. 25% is the markup on cost (20/80), a common mix-up.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-3","question":"Which sequence correctly describes the standard consumer buying-decision process?","options":["Awareness → interest → desire → action → loyalty","Information search → need recognition → purchase decision → evaluation of alternatives → post-purchase behaviour","Need recognition → evaluation of alternatives → information search → purchase decision → post-purchase behaviour","Need recognition → information search → evaluation of alternatives → purchase decision → post-purchase behaviour"],"answer":3,"explanation":"The five-stage model runs from need recognition through search, evaluation and purchase to post-purchase behaviour. The last option is the AIDA response model used for communication, not the buying process.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-4","question":"A distributor prices all products at a 25% markup on cost. What margin on selling price does this give?","options":["25%","33.3%","20%","18%"],"answer":2,"explanation":"Margin = markup / (1 + markup) = 0.25 / 1.25 = 20%. Markup is on cost; margin is on selling price, so the margin figure is always smaller.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-5","question":"A typewriter manufacturer kept defining its business as \"making the best typewriters\" while customers moved to computers for document writing. The failure is best described as:","options":["Cognitive dissonance","Marketing myopia","Cannibalisation","Brand dilution"],"answer":1,"explanation":"Marketing myopia is defining a business by its current product instead of the customer need it serves (here, producing documents). The firm misses substitutes that meet the same need.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-6","question":"A cola brand creates a loyalty scheme only for customers who buy more than 20 bottles a month. Which segmentation base is it using?","options":["Behavioural (usage rate)","Psychographic","Demographic","Geographic"],"answer":0,"explanation":"Segmenting by how much a customer buys (heavy, medium, light users) is behavioural segmentation on usage rate.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-7","question":"Assertion (A): A segment of 2,000 rare-coin collectors scattered across the country, with no common media or outlet, may be a poor target even if each spends heavily.\nReason (R): For a segment to be useful it must be accessible — the firm must be able to reach and serve it effectively.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"A segment must be measurable, substantial, accessible, differentiable and actionable. A high-value but unreachable group fails the accessibility test, which is exactly why A holds.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-8","question":"Shoppers frequently switch between biscuit brands just to try something new, even though they are happy with their last pack. The category is low involvement and brands differ noticeably. This is:","options":["Complex buying behaviour","Dissonance-reducing buying behaviour","Habitual buying behaviour","Variety-seeking buying behaviour"],"answer":3,"explanation":"Low involvement with significant brand differences produces variety-seeking behaviour. Market leaders respond by dominating shelf space and running reminder advertising; challengers use deals and samples to invite switching.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-9","question":"A customer buys an expensive air conditioner after comparing a few brands she felt were broadly similar. A week later she worries she chose wrongly. What should the marketer prioritise?","options":["Post-purchase reassurance: follow-up calls, warranty reminders and reinforcing communication","Deeper price discounts for new buyers","Launching more variants to widen choice","Reducing advertising since the sale is complete"],"answer":0,"explanation":"High involvement with few perceived brand differences leads to dissonance-reducing behaviour. Post-purchase communication that confirms the choice reduces the doubt (cognitive dissonance) and protects word of mouth.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-10","question":"A biscuit pack has an MRP of ₹50. The retailer earns 20% margin on its selling price and the distributor earns 10% margin on its own selling price. At what price does the company sell to the distributor (ignore taxes)?","options":["₹35","₹36","₹37.50","₹40"],"answer":1,"explanation":"Retailer buys at 50 × 0.8 = ₹40, which is the distributor's selling price. Distributor buys at 40 × 0.9 = ₹36. Adding margins (50 × 0.7 = ₹35) is the classic error because each margin is on a different base.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-11","question":"A brand cuts its price by 10% and unit sales rise by 25%. What happens to sales revenue?","options":["It rises by 15%","It rises by 2.5%","It rises by 12.5%","It falls by 10%"],"answer":2,"explanation":"New revenue = 0.9 × 1.25 = 1.125 of the old, a 12.5% rise. Simply subtracting percentages (25 − 10 = 15%) ignores that the two changes multiply. Elasticity here is −2.5, so demand is elastic and a price cut raises revenue.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-12","question":"An edtech landing page gets 20,000 visitors in a month. 5% sign up as leads, 30% of leads are qualified by the sales team, and 20% of qualified leads buy. How many customers does the funnel produce?","options":["300","60","1,100","600"],"answer":1,"explanation":"20,000 × 0.05 = 1,000 leads → × 0.30 = 300 qualified → × 0.20 = 60 customers. Funnel conversion rates multiply stage by stage.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-13","question":"A B2B sales manager needs 90 closed deals next quarter. Historically 40% of leads become meetings, 50% of meetings become proposals and 25% of proposals close. How many leads must the team generate?","options":["900","1,200","2,250","1,800"],"answer":3,"explanation":"Overall conversion = 0.40 × 0.50 × 0.25 = 5%. Leads needed = 90 / 0.05 = 1,800. Dividing by only one stage rate understates the requirement.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-14","question":"A campaign spends ₹30,000, gets 6,00,000 impressions, 4,800 clicks and 120 purchases. What is the cost per acquisition (CPA)?","options":["₹6.25","₹50","₹250","₹2,500"],"answer":2,"explanation":"CPA = spend / conversions = 30,000 / 120 = ₹250. ₹6.25 is the CPC (30,000 / 4,800) and ₹50 is the CPM (30,000 / 6,00,000 × 1,000).","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-15","question":"A display campaign costs ₹36,000 for 12,00,000 impressions with a click-through rate of 0.4%. What is the cost per click?","options":["₹3.00","₹0.75","₹30.00","₹7.50"],"answer":3,"explanation":"Clicks = 12,00,000 × 0.004 = 4,800. CPC = 36,000 / 4,800 = ₹7.50. ₹30 is the CPM (cost per thousand impressions), not the CPC.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-16","question":"A D2C brand spends ₹2 lakh on ads that generate ₹7 lakh of revenue. Its gross margin is 25%. Which statement is correct?","options":["ROAS is 3.5x, but the campaign loses ₹25,000 after ad spend","ROAS is 3.5x and the campaign earns ₹5 lakh profit","ROAS is 2.5x and the campaign earns ₹1.75 lakh profit","ROAS is 3.5x and the campaign earns ₹1.75 lakh profit"],"answer":0,"explanation":"ROAS = 7 / 2 = 3.5x. Gross profit on the sales = 7 × 0.25 = ₹1.75 lakh, which is less than the ₹2 lakh spent, so the campaign loses ₹25,000. ROAS measures revenue per rupee of spend, not profit.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-17","question":"A company's gross margin is 40%. What is the minimum ROAS at which ad spend just pays for itself (before other costs)?","options":["1.4x","2.5x","4.0x","0.4x"],"answer":1,"explanation":"Break-even ROAS = 1 / gross margin = 1 / 0.40 = 2.5x. At 2.5x, each ₹1 of spend brings ₹2.50 of revenue and ₹1 of gross profit, exactly covering the spend.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-18","question":"In an NPS survey of 500 customers, 260 give scores of 9–10, 140 give 7–8 and 100 give 0–6. What is the Net Promoter Score?","options":["52","72","32","24"],"answer":2,"explanation":"Promoters = 260/500 = 52%; detractors = 100/500 = 20%; NPS = 52 − 20 = 32. Passives count in the base but not in the score.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-19","question":"A survey of 200 customers has 90 promoters, 70 passives and 40 detractors. If service fixes convert 20 of the detractors into passives, by how many points does the NPS rise?","options":["10","20","5","15"],"answer":0,"explanation":"Before: (90 − 40)/200 = 25. After: (90 − 20)/200 = 35. The rise is 10 points. Moving a detractor to passive lifts NPS by half as much as moving one to promoter.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-20","question":"A subscription app earns ₹600 per user per month at a 50% gross margin. Monthly churn is 4%. Using the simple formula, what is the customer lifetime value (gross-margin basis)?","options":["₹15,000","₹7,500","₹12,000","₹300"],"answer":1,"explanation":"Average lifetime = 1/0.04 = 25 months. LTV = 600 × 0.5 × 25 = ₹7,500. ₹15,000 uses revenue instead of margin.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-21","question":"A SaaS firm spends ₹4,500 to acquire a customer who contributes ₹300 of gross margin per month. Monthly churn is 5%. Which assessment is correct?","options":["LTV:CAC is about 0.7 and payback is 15 months — every customer loses money","LTV:CAC is about 3 and payback is 15 months — unit economics are healthy","LTV:CAC is about 1.3 and payback is 20 months — unit economics look weak","LTV:CAC is about 1.3 and payback is 15 months — unit economics look weak"],"answer":3,"explanation":"LTV = 300 / 0.05 = ₹6,000, so LTV:CAC = 6,000 / 4,500 ≈ 1.33. Payback = 4,500 / 300 = 15 months. Against the common 3:1 benchmark this is weak, though still above 1.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-22","question":"A streaming service starts the quarter with 1,000 subscribers, adds 200 new subscribers during the quarter and ends with 1,050. What is the churn rate for the quarter?","options":["5%","19%","15%","20%"],"answer":2,"explanation":"Customers retained from the start = 1,050 − 200 = 850, so retention = 85% and churn = 15%. The net growth of 5% hides the loss of 150 original subscribers.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-23","question":"A firm launches a patented medical gadget. Early buyers are hospitals that care more about capability than price, and the factory can make only limited units in the first year. Which pricing strategy fits best?","options":["Market-penetration pricing","Market-skimming pricing","Loss-leader pricing","Everyday low pricing"],"answer":1,"explanation":"Skimming works when early buyers are price-insensitive, competitors are blocked (patent) and capacity is limited — high prices ration supply and recover R&D before lowering prices for later segments.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-24","question":"A messaging app's value rises as more people join, and its target market is very price-sensitive. Which pricing approach is most appropriate at launch?","options":["Penetration (even free) pricing, to build the user base fast","Prestige pricing, to signal quality","Skimming, to recover development cost quickly","Cost-plus pricing at a high markup"],"answer":0,"explanation":"Network effects plus elastic demand favour penetration pricing: a large base quickly increases value for every user and raises barriers for rivals.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-25","question":"Match each product range with the segmentation base it uses.\nA. A cream made only for humid coastal regions\nB. A range for working women aged 25–40\nC. A range for 'health-obsessed fitness enthusiasts'\nD. Special gift packs for festival buyers\n1. Behavioural (occasion)  2. Geographic  3. Psychographic  4. Demographic","options":["A-2, B-4, C-1, D-3","A-2, B-3, C-4, D-1","A-4, B-2, C-3, D-1","A-2, B-4, C-3, D-1"],"answer":3,"explanation":"Region = geographic; age and occupation = demographic; lifestyle and values = psychographic; buying occasion (festivals) = behavioural.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-26","question":"Consider these statements about perceptual (positioning) maps:\nI. A gap on the map always signals an unmet demand worth entering.\nII. Maps should be built from customer perceptions, not engineering specifications.\nIII. The attributes chosen for the axes decide which gaps appear.\nWhich are correct?","options":["I, II and III","I and II only","II and III only","III only"],"answer":2,"explanation":"II and III are correct. A gap may exist because no customer wants that combination (for example, low price with ultra-premium design), so statement I is false; demand must be tested before entering.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-27","question":"A smartwatch brand has won the innovators and early adopters as defined in Rogers' diffusion model. What share of eventual adopters has it reached?","options":["2.5%","13.5%","16%","50%"],"answer":2,"explanation":"Innovators (2.5%) + early adopters (13.5%) = 16%. The early majority (34%) is next; crossing from early adopters to the pragmatic early majority is often the hardest step.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-28","question":"Assertion (A): Penetration pricing is a poor choice when a firm cannot expand capacity in the short run.\nReason (R): Low prices create demand that capacity cannot meet, so the firm sacrifices margin on volume it has to ration anyway.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Penetration pricing earns its return through volume. With fixed capacity the extra demand cannot be served, so the firm gives up margin without gaining volume — R explains A.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-29","question":"A product costs ₹120 per unit (all variable) and sells at ₹150. Management cuts the price by 10%. By what percentage must unit sales rise to keep total contribution unchanged?","options":["10%","25%","50%","100%"],"answer":3,"explanation":"Contribution per unit falls from ₹30 to ₹135 − ₹120 = ₹15. To keep total contribution the same, volume must double: a 100% increase. A small price cut on a thin margin needs a huge volume gain.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-30","question":"An advertisement for a home-security system shows a family sleeping peacefully while the system guards the house. Which level of Maslow's hierarchy does it appeal to?","options":["Physiological","Esteem","Social (belonging)","Safety"],"answer":3,"explanation":"Protection from danger and threats is the safety need. Marketers align the message with the need the product satisfies.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-31","question":"In which stage of the product life cycle do sales usually peak, growth slows and competitors fight mainly on price and promotion?","options":["Introduction","Maturity","Growth","Decline"],"answer":1,"explanation":"Maturity is the longest stage: most potential buyers already own the product, sales level off and competition shifts to price, promotion and small differentiation.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-32","question":"Services marketing extends the traditional 4P mix to 7P. Which of these is one of the three added elements?","options":["Price","Promotion","People","Place"],"answer":2,"explanation":"The extra three are people, process and physical evidence. Price, place and promotion are part of the original 4P.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-33","question":"A TV maker offers free installation, a three-year extended warranty and a home demo with every set. At which product level do these benefits sit?","options":["Core benefit","Augmented product","Expected product","Basic product"],"answer":1,"explanation":"The augmented product adds services and benefits beyond what buyers normally expect, helping the brand stand apart from competitors.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-34","question":"A firm is launching a product into a large market where buyers are unaware of the category, highly price-sensitive, competitors could enter soon, and unit costs fall sharply with volume. Which introduction strategy fits?","options":["Rapid skimming (high price, heavy promotion)","Slow skimming (high price, low promotion)","Slow penetration (low price, low promotion)","Rapid penetration (low price, heavy promotion)"],"answer":3,"explanation":"Unaware buyers need heavy promotion; price sensitivity, scale economies and the threat of entry call for a low price. Together that is rapid penetration. Slow penetration suits a market that already knows the category.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-35","question":"A mature baking-soda brand starts advertising its use as a fridge deodoriser and a cleaning agent. Which maturity-stage strategy is this?","options":["Product modification","Marketing-mix modification","Market modification (new uses and higher usage)","Harvesting"],"answer":2,"explanation":"Market modification grows volume by finding new users or increasing usage — including promoting new uses for the unchanged product. Product modification would change the product itself.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-36","question":"A company cuts all promotion and R&D for a declining product while keeping it on shelves to collect cash for as long as possible. This is:","options":["Divesting","Rejuvenation","Repositioning","Harvesting"],"answer":3,"explanation":"Harvesting reduces costs gradually while sales continue, boosting short-term cash flow. Divesting means selling or dropping the product altogether.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-37","question":"A toothpaste brand that sells well in India starts selling the same product in East African markets. In Ansoff's matrix, this is:","options":["Market development","Market penetration","Product development","Diversification"],"answer":0,"explanation":"Existing product, new market = market development. Product development would be a new product for existing customers.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-38","question":"A dairy firm launches a range of flavoured yoghurts to the same households that already buy its milk. In Ansoff's matrix this is:","options":["Market penetration","Product development","Market development","Diversification"],"answer":1,"explanation":"A new product for existing customers is product development.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-39","question":"Why is diversification usually considered the riskiest of Ansoff's four growth strategies?","options":["It needs the largest advertising budget","It always involves an acquisition","Both the product and the market are new to the firm, so it has little experience in either","It reduces the firm's existing market share"],"answer":2,"explanation":"Diversification combines a new product with a new market, so the firm cannot rely on its existing knowledge of customers or of the product.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-40","question":"A chocolate brand adds a new orange flavour to its bar range, and separately uses the same brand name to launch an ice-cream range. These are, respectively:","options":["Line extension and brand (category) extension","Brand extension and line extension","Co-branding and line extension","Line extension and multibranding"],"answer":0,"explanation":"A new flavour, size or variant within the same category is a line extension. Using the brand in a new category (ice cream) is a brand or category extension.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-41","question":"Which brand architecture best limits the risk that one product's failure or scandal damages the company's other products, though it is costlier to build?","options":["Branded house (one master brand on everything)","House of brands (separate stand-alone brands)","Endorsed brands","Sub-brands under a master brand"],"answer":1,"explanation":"In a house of brands each brand stands alone, so trouble in one does not spill over to the others. The cost is that every brand needs its own marketing investment.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-42","question":"Consider these statements about brand extensions:\nI. A good fit between the parent brand and the new category improves acceptance.\nII. An extension can never hurt the parent brand if it is in a different category.\nIII. Successful extensions can lower launch costs because awareness already exists.\nWhich are correct?","options":["II and III only","I, II and III","I and II only","I and III only"],"answer":3,"explanation":"I and III are correct. II is false: a poor or failed extension in another category can still dilute the parent brand's associations.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-43","question":"In Keller's customer-based brand equity pyramid, which block sits at the top?","options":["Brand salience","Brand performance","Brand resonance","Brand judgements"],"answer":2,"explanation":"The pyramid rises from salience (identity) to performance and imagery (meaning), then judgements and feelings (response) and finally resonance — an intense, active loyalty relationship.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-44","question":"A home-automation kit is adopted slowly: buyers find it difficult to set up and cannot try it before paying. Which two Rogers adoption characteristics explain this, and what is the fitting remedy?","options":["Relative advantage and compatibility — cut the price","Complexity and trialability — simplify set-up and offer free trials or demos","Observability and compatibility — increase advertising","Relative advantage and observability — add features"],"answer":1,"explanation":"High complexity and low trialability slow adoption. Plug-and-play installation, demos and free trials attack both directly.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-45","question":"A new shampoo variant sells 50,000 units; 40% of those buyers would otherwise have bought the brand's existing variant. Contribution is ₹25 per unit on the new variant and ₹20 per unit on the existing one. What is the net incremental contribution?","options":["₹8.5 lakh","₹12.5 lakh","₹7.5 lakh","₹10.5 lakh"],"answer":0,"explanation":"Gross gain = 50,000 × 25 = ₹12.5 lakh. Lost sales of the old variant = 20,000 × ₹20 = ₹4 lakh. Net = ₹8.5 lakh. Valuing the lost units at ₹25 (giving ₹7.5 lakh) or ignoring cannibalisation (₹12.5 lakh) are the usual errors.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-46","question":"In which product life cycle stage are profits typically negative or very low and the promotion-to-sales ratio at its highest?","options":["Decline","Growth","Maturity","Introduction"],"answer":3,"explanation":"At introduction sales are small and the firm spends heavily to build awareness, distribution and trial, so profits are low or negative.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-47","question":"A novelty toy becomes a craze for a few months and then sales collapse almost as quickly as they rose. Its life cycle pattern is that of a:","options":["Style","Fashion","Fad","Scalloped (repeated) cycle"],"answer":2,"explanation":"Fads rise quickly, are adopted with great zeal, peak early and decline fast. Styles last for generations, and fashions pass through slower, regular cycles.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-48","question":"In the BCG matrix, a product with a high relative market share in a low-growth market is a:","options":["Star","Question mark","Dog","Cash cow"],"answer":3,"explanation":"A cash cow generates more cash than it needs; firms usually 'milk' it to fund stars and selected question marks.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-49","question":"A brand holds 15% share in a market growing at 18% a year; the leader holds 30%. Using the BCG convention (high growth above about 10%, relative share above 1.0 is high), how is the brand classified?","options":["Question mark","Star","Cash cow","Dog"],"answer":0,"explanation":"Relative market share = 15 / 30 = 0.5 (low) in a high-growth market, so the brand is a question mark that needs investment to become a star or should be divested.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-50","question":"A company sells three product lines: soaps (4 brands), shampoos (3 brands) and toothpastes (2 brands). What are the width and length of its product mix?","options":["Width 9, length 3","Width 3, length 9","Width 3, length 3","Width 4, length 9"],"answer":1,"explanation":"Width = number of product lines (3). Length = total number of items/brands across lines (4 + 3 + 2 = 9). Depth would be the variants of each brand.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-51","question":"Assertion (A): In the maturity stage, many FMCG firms shift budget from advertising toward trade and consumer sales promotions.\nReason (R): In maturity most buyers already know the category and brands, so switching is driven largely by deals and availability.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"With awareness already high, the marginal rupee works harder as a deal or display that triggers switching than as more awareness advertising — R explains A.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-52","question":"A robotics start-up has won tech enthusiasts but sales have stalled before reaching pragmatic mainstream buyers. Which approach best helps it cross this 'chasm'?","options":["Focus on one niche of pragmatic buyers and give them a complete, proven solution with peer references","Cut prices across all segments at once","Add more advanced features to impress enthusiasts","Shift all spending to mass-media brand advertising"],"answer":0,"explanation":"Mainstream (early majority) buyers want proven, complete solutions and references from people like them. Dominating one niche first creates those references; more features appeal only to enthusiasts.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-53","question":"In a store test, shoppers pay ₹60 for a branded ghee pack and ₹48 for an otherwise identical unbranded pack. What price premium does the brand command?","options":["20%","12%","25%","80%"],"answer":2,"explanation":"Price premium = (60 − 48) / 48 = 25% over the unbranded product. 20% divides by the branded price instead.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-54","question":"A laptop maker displays the logo of its processor supplier on every machine and in its advertising. This is an example of:","options":["Private labelling","Ingredient branding","Line extension","Multibranding"],"answer":1,"explanation":"Ingredient branding promotes a component brand inside the final product, so the host product borrows the component's credibility.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-55","question":"Match each PLC stage with its typical marketing objective.\nA. Introduction  B. Growth  C. Maturity  D. Decline\n1. Reduce spending and harvest, or divest\n2. Build awareness and trial\n3. Maximise share: add features, models and channels\n4. Defend share and extend life by modifying market, product or mix","options":["A-2, B-3, C-1, D-4","A-2, B-4, C-3, D-1","A-3, B-2, C-4, D-1","A-2, B-3, C-4, D-1"],"answer":3,"explanation":"Introduction builds awareness and trial, growth maximises share, maturity defends share and extends life, and decline cuts costs and harvests or exits.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-56","question":"Which of these statements about the product life cycle are correct?\nI. Every product follows the same S-shaped curve.\nII. Marketing actions can extend the maturity stage.\nIII. A life cycle can be drawn for a category, a product form or a single brand.\nIV. The PLC reliably predicts how long each stage will last.","options":["II and III only","I, II and III only","II, III and IV only","I and IV only"],"answer":0,"explanation":"II and III are correct. Shapes vary widely (fads, styles, scalloped cycles), and the PLC describes patterns after the fact rather than forecasting exact stage lengths.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-57","question":"A water-purifier category has a potential of 10 lakh households and adoption follows Rogers' adopter categories. Once the entire early majority has adopted, how many households have not yet adopted?","options":["3.4 lakh","8.4 lakh","1.6 lakh","5 lakh"],"answer":3,"explanation":"Innovators 2.5% + early adopters 13.5% + early majority 34% = 50% adopted, so 50% (5 lakh households) — the late majority and laggards — remain.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-58","question":"Assertion (A): A failed extension in a distant category can weaken the parent brand.\nReason (R): Consumers update their beliefs about a brand using information from every product that carries its name.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because associations are shared across products with the same name, a bad experience with the extension can feed back to the parent — R explains A.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-59","question":"A premium watch brand launches a much cheaper line under the same brand name to reach mass buyers. What is the biggest marketing risk of this downward stretch?","options":["Retailers will refuse to stock the premium range","The cheaper line may cannibalise premium sales and dilute the brand's exclusive image","Production costs of the premium line will rise","It will reduce the brand's awareness among mass buyers"],"answer":1,"explanation":"Downward line stretching can pull existing buyers to the cheaper line and weaken the prestige that justified premium prices. Many firms use a separate or sub-brand to limit this.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-60","question":"A brand prices its earphones at ₹499 instead of ₹500 because buyers tend to read it as 'four hundred and something'. This is:","options":["Prestige pricing","Cost-plus pricing","Charm (odd) pricing, a form of psychological pricing","Captive-product pricing"],"answer":2,"explanation":"Charm or odd pricing ends prices just below a round figure so the price feels noticeably lower. It is a psychological pricing tactic.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-61","question":"A manufacturer's unit cost is ₹200 and it adds a standard 30% markup on cost. What is its selling price?","options":["₹230","₹270","₹285.71","₹260"],"answer":3,"explanation":"Cost-plus price = 200 × 1.30 = ₹260. ₹285.71 would give a 30% margin on the selling price (200 / 0.70), which is a different rule.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-62","question":"A retailer wants a 40% margin on its selling price. What markup on cost must it apply?","options":["40%","60%","66.7%","28.6%"],"answer":2,"explanation":"Markup = margin / (1 − margin) = 0.40 / 0.60 = 66.7%. Example: cost ₹60, price ₹100 gives a ₹40 profit — 40% of price but 66.7% of cost.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-63","question":"A firm has fixed costs of ₹6 lakh. Its product sells for ₹250 with a variable cost of ₹150 per unit. What is the break-even volume?","options":["2,400 units","4,000 units","10,000 units","6,000 units"],"answer":3,"explanation":"Break-even units = fixed cost / unit contribution = 6,00,000 / (250 − 150) = 6,000 units. 2,400 divides by the price instead of the contribution.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-64","question":"Demand for a commuter bus pass has a price elasticity of −0.5. If the fare rises by 10%, roughly what happens to revenue?","options":["It falls by about 5%","It rises by about 10%","It rises by about 4.5%","It falls by about 15%"],"answer":2,"explanation":"Quantity falls about 5% (−0.5 × 10%). Revenue = 1.10 × 0.95 = 1.045, a rise of about 4.5%. With inelastic demand, a price rise increases revenue.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-65","question":"A cinema sells popcorn: small ₹150, medium ₹270, large ₹290. Few people buy the medium, but large sales are high. The medium tub's main role is to:","options":["Act as a decoy that makes the large tub look like a bargain","Serve the most price-sensitive buyers","Reduce wastage of popcorn","Act as a loss leader to draw people into the cinema"],"answer":0,"explanation":"The medium is priced close to the large so that the large appears to offer far more for only ₹20 extra. This is the decoy effect.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-66","question":"A luxury perfume is deliberately priced at a high, round ₹10,000, though costs would allow a far lower price. This strategy is:","options":["Going-rate pricing","Penetration pricing","Charm pricing","Prestige pricing"],"answer":3,"explanation":"Prestige pricing uses a high price as a signal of quality and status; for such goods a lower price can actually reduce demand. Round figures reinforce the premium image.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-67","question":"A printer is sold close to cost, while the replacement ink cartridges carry very high margins. This is:","options":["Product-bundle pricing","Optional-product pricing","Captive-product pricing","By-product pricing"],"answer":2,"explanation":"Captive-product pricing prices the main product low and earns profit on the supplies that must be used with it (cartridges, razor blades, coffee pods).","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-68","question":"A firm's unit cost is ₹16, it has invested ₹10 lakh and wants a 20% return on investment. It expects to sell 50,000 units. What is the target-return price?","options":["₹20","₹19.20","₹36","₹18"],"answer":0,"explanation":"Target-return price = unit cost + (ROI × investment) / units = 16 + (0.20 × 10,00,000) / 50,000 = 16 + 4 = ₹20. ₹19.20 applies 20% to the unit cost instead.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-69","question":"A trader's cost is ₹120 and she wants a 25% margin on the selling price. What price must she set?","options":["₹150","₹170","₹145","₹160"],"answer":3,"explanation":"Price = cost / (1 − margin) = 120 / 0.75 = ₹160 (profit ₹40 is 25% of ₹160). ₹150 is a 25% markup on cost, which is only a 20% margin.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-70","question":"Fixed costs are ₹4,00,000, the price is ₹80 and variable cost is ₹48 per unit. How many units must be sold to earn a profit of ₹2,40,000?","options":["20,000","12,500","8,000","13,333"],"answer":0,"explanation":"Units = (fixed cost + target profit) / unit contribution = (4,00,000 + 2,40,000) / 32 = 20,000. 12,500 is only the break-even volume.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-71","question":"A company's fixed costs are ₹9 lakh and its contribution margin ratio is 30%. What sales revenue does it need to break even?","options":["₹2.7 lakh","₹12.9 lakh","₹30 lakh","₹27 lakh"],"answer":2,"explanation":"Break-even revenue = fixed cost / CM ratio = 9 / 0.30 = ₹30 lakh. Multiplying instead of dividing gives ₹2.7 lakh.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-72","question":"A company sells a pack to its distributor at ₹72. The distributor earns 10% on its own selling price, and the retailer earns 20% on the MRP. What MRP should be printed (ignore taxes)?","options":["₹93.60","₹100","₹97.20","₹102.86"],"answer":1,"explanation":"Distributor's selling price = 72 / 0.9 = ₹80. MRP = 80 / 0.8 = ₹100. Adding 10% and 20% on cost (72 × 1.1 × 1.2 = ₹95.04) or adding margins together (72 × 1.3 = ₹93.60) are the usual errors.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-73","question":"An MRP of ₹200 is shared along the chain: the retailer earns 15% on MRP, the wholesaler 8% on its selling price and the super-stockist 4% on its selling price. What does the company realise per unit (ignore taxes)?","options":["₹146.00","₹150.14","₹154.00","₹156.40"],"answer":1,"explanation":"Retailer buys at 200 × 0.85 = ₹170; wholesaler buys at 170 × 0.92 = ₹156.40; super-stockist buys at 156.40 × 0.96 = ₹150.14. Subtracting 27% of MRP (₹146) is wrong because each margin is on a different base.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-74","question":"When a store raises the price of a juice from ₹40 to ₹50, weekly sales fall from 1,000 to 800 packs. Using the midpoint (arc) method, the price elasticity of demand is:","options":["−0.8","−1.0 (unit elastic)","−1.25","−0.2"],"answer":1,"explanation":"%ΔQ = −200 / 900 = −22.2%; %ΔP = 10 / 45 = 22.2%. Elasticity = −1.0, so revenue barely changes (₹40,000 both before and after). Using the starting values gives −0.8, which overstates inelasticity.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-75","question":"A firm faces a constant price elasticity of demand of −3 and a marginal cost of ₹40. Using the profit-maximising markup rule P = MC × E / (E + 1), what price should it charge?","options":["₹53.33","₹60","₹120","₹80"],"answer":1,"explanation":"P = 40 × (−3) / (−3 + 1) = 40 × 1.5 = ₹60. The more elastic the demand, the smaller the optimal markup over marginal cost.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-76","question":"A product sells at ₹100 with a variable cost of ₹60; current volume is 10,000 units. If the price is cut by 5%, by roughly what percentage must volume rise to keep total contribution unchanged?","options":["5%","14.3%","12.5%","8.3%"],"answer":1,"explanation":"Contribution per unit falls from ₹40 to ₹35. Required volume = 10,000 × 40 / 35 ≈ 11,429, a rise of about 14.3%. Small price cuts need much larger volume gains when margins are thin.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-77","question":"A product sells at ₹100 with a variable cost of ₹60 and current volume of 8,000 units. If the price is raised by 10%, by how much can volume fall before total contribution drops below today's level?","options":["10%","16.7%","20%","25%"],"answer":2,"explanation":"Contribution per unit rises from ₹40 to ₹50. Break-even volume = 8,000 × 40 / 50 = 6,400, a 20% fall. Any smaller loss in volume makes the price rise profitable.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-78","question":"Consider these statements:\nI. Skimming suits markets where early buyers are relatively insensitive to price.\nII. Penetration suits markets where unit costs fall sharply with volume.\nIII. Skimming discourages competitors from entering.\nWhich are correct?","options":["I and III only","I, II and III","II and III only","I and II only"],"answer":3,"explanation":"I and II are correct. III is false: the high margins of skimming tend to attract competitors; it is penetration pricing that discourages entry.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-79","question":"An online store shows a jacket as 'MRP ₹1,999 — now ₹1,299'. The struck-out MRP mainly works as:","options":["An external reference price that makes the offer look like a gain","A cost-plus price signal","A captive-product price","A going-rate price"],"answer":0,"explanation":"Showing a higher reference price lets buyers judge the current price as a saving. This framing is a common psychological pricing tool.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-80","question":"A firm wants to charge students a lower price than other buyers for the same software. Which conditions must hold for this segmented pricing to work?\nI. The segments differ in price sensitivity.\nII. Low-price buyers cannot easily resell to high-price buyers.\nIII. The cost of segmenting and policing the market is less than the extra revenue.\nIV. Every segment must pay above the firm's average total cost.","options":["I and II only","I, II and III only","I, II, III and IV","II and IV only"],"answer":1,"explanation":"Segmented pricing needs different elasticities, no easy arbitrage and benefits greater than costs. IV is not required — a low-price segment only needs to cover its variable cost and add some contribution.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-81","question":"Assertion (A): If demand for a product is price-inelastic, a moderate price increase raises total revenue.\nReason (R): With inelastic demand, the percentage fall in quantity is smaller than the percentage rise in price.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Revenue = price × quantity. If |E| < 1, quantity falls proportionally less than price rises, so revenue increases — R explains A directly.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-82","question":"Two customers value a streaming service (X) and a music app (Y) as follows: Customer 1 — X ₹500, Y ₹300; Customer 2 — X ₹300, Y ₹500. Each product has zero marginal cost. Compared with the best separate prices, how much more revenue does a bundle priced at ₹800 earn?","options":["₹400","₹200","₹600","₹0"],"answer":0,"explanation":"Separately, the best is ₹300 per product (both buy both): 4 × 300 = ₹1,200 (pricing at ₹500 gives only ₹1,000). The bundle at ₹800 is bought by both: ₹1,600. Gain = ₹400. Bundling works because the valuations are negatively correlated.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-83","question":"A 'Buy 2, Get 1 Free' offer is equivalent to what percentage discount on the three units?","options":["66.7%","50%","25%","33.3%"],"answer":3,"explanation":"The customer pays for 2 units and gets 3, so the discount is 1/3 ≈ 33.3% of the total value. 50% compares the free unit with the units paid for.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-84","question":"A wholesaler's list price is ₹1,000. A retailer gets a 20% trade discount and then a 5% cash discount for paying early. How much does the retailer pay?","options":["₹750","₹800","₹760","₹950"],"answer":2,"explanation":"After the trade discount: 1,000 × 0.80 = ₹800. After the cash discount: 800 × 0.95 = ₹760. Adding the discounts (25%, giving ₹750) is wrong because they apply in sequence.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-85","question":"A product costs the manufacturer ₹50. The manufacturer adds a 40% markup on cost, the wholesaler 20% on its cost and the retailer 25% on its cost. What is the retail price?","options":["₹92.50","₹110","₹100","₹105"],"answer":3,"explanation":"50 × 1.40 = ₹70 → × 1.20 = ₹84 → × 1.25 = ₹105. Adding the markups (85% on ₹50 = ₹92.50) ignores compounding.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-86","question":"A company plans an MRP of ₹100. The retailer needs 20% on MRP and the distributor 8% on its own selling price. If the company's unit cost is ₹55, what margin does the company earn on its own selling price?","options":["About 33.8%","About 25.3%","About 18.6%","About 17%"],"answer":1,"explanation":"Company's selling price = 100 × 0.80 × 0.92 = ₹73.60. Margin = (73.60 − 55) / 73.60 ≈ 25.3%. 33.8% is the markup on cost (18.60 / 55).","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-87","question":"A software firm's tool saves a client ₹10 lakh a year, and it sets the annual fee at ₹3 lakh regardless of its own cost to serve. This is:","options":["Cost-plus pricing","Going-rate pricing","Value-based pricing","Penetration pricing"],"answer":2,"explanation":"Value-based pricing starts from the value the customer perceives (here, the savings) and sets a price below it, rather than adding a markup to cost.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-88","question":"A supermarket keeps prices consistently low all year and runs very few temporary promotions. This is called:","options":["Everyday low pricing (EDLP)","High–low pricing","Skimming","Loss-leader pricing"],"answer":0,"explanation":"EDLP keeps prices steadily low, saving promotion costs and building trust. High–low pricing uses higher regular prices with frequent deep promotions.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-89","question":"A pickle maker sells only through its own website and delivers straight to consumers. What kind of channel is this?","options":["Three-level channel","One-level channel","Two-level channel","Zero-level (direct) channel"],"answer":3,"explanation":"A zero-level channel has no intermediaries: the manufacturer sells directly to the consumer. Each intermediary (retailer, wholesaler, agent) adds one level.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-90","question":"A new drink brand runs heavy TV and social-media ads so that consumers ask shopkeepers for it by name. This is primarily a:","options":["Push strategy","Trade-promotion strategy","Pull strategy","Personal-selling strategy"],"answer":2,"explanation":"A pull strategy builds consumer demand that 'pulls' the product through the channel. A push strategy uses trade incentives and the sales force to push the product through intermediaries.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-91","question":"Which type of distribution suits a low-priced convenience product such as salt or matchboxes?","options":["Intensive distribution","Selective distribution","Exclusive distribution","Direct distribution only"],"answer":0,"explanation":"Convenience goods are bought frequently with little effort, so they must be available in as many outlets as possible — intensive distribution.","difficulty":"easy","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-92","question":"A premium car brand appoints only one dealer in each city and does not let dealers sell competing brands. This is:","options":["Intensive distribution","Exclusive distribution","Selective distribution","Multichannel distribution"],"answer":1,"explanation":"Exclusive distribution gives a single dealer the rights in a territory, often with exclusive-dealing terms. It supports service quality and premium image.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-93","question":"An appliance maker starts selling on its own website at prices lower than those its dealers charge. Dealers protest. This is best described as:","options":["Horizontal channel conflict","Channel cooperation","Vertical integration","Multichannel conflict"],"answer":3,"explanation":"Multichannel conflict arises when a producer uses two or more channels that compete for the same buyers. Horizontal conflict is between members at the same level, such as two dealers of the same brand.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-94","question":"A restaurant chain grows by signing franchise agreements under which independent owners use its brand, menu and systems. Which vertical marketing system is this?","options":["Corporate VMS","Administered VMS","Contractual VMS","Horizontal marketing system"],"answer":2,"explanation":"Franchising links independent firms through contracts, so it is a contractual VMS. A corporate VMS uses common ownership; an administered VMS relies on the size and power of a dominant member.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-95","question":"Which promotion tool is usually seen by audiences as the most credible because the message does not appear to be paid for by the company?","options":["Advertising","Public relations and publicity","Sales promotion","Direct mail"],"answer":1,"explanation":"News stories and features carry more credibility than ads because they appear to come from an independent source. The trade-off is less control over the message.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-96","question":"A brand's TV ads promise 'luxury', its social posts push deep discounts and in-store displays emphasise 'family value'. Customers are confused. What does the brand need?","options":["Integrated marketing communications (IMC)","A bigger media budget","More sales-promotion schemes","A shift to a pure push strategy"],"answer":0,"explanation":"IMC coordinates all communication tools so they carry one clear, consistent message and positioning.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-97","question":"A firm has 1,000 'A' accounts needing 24 calls a year and 2,000 'B' accounts needing 12 calls a year. Each sales rep can make 1,200 calls a year. Using the workload approach, how many reps are needed?","options":["20","30","60","40"],"answer":3,"explanation":"Total calls = 1,000 × 24 + 2,000 × 12 = 48,000. Reps = 48,000 / 1,200 = 40.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-98","question":"A rep's quarterly quota is ₹50 lakh. She earns a fixed salary plus an incentive of 2% on sales above 80% of quota. She sells ₹55 lakh in the quarter. What is her incentive?","options":["₹10,000","₹1,10,000","₹30,000","₹1,00,000"],"answer":2,"explanation":"The threshold is 80% × 50 = ₹40 lakh. Incentive = 2% × (55 − 40) lakh = ₹30,000. Paying 2% on all sales gives ₹1.1 lakh, and paying only on sales above quota gives ₹10,000.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-99","question":"Which of these is NOT a sound principle of sales-territory design?","options":["Territories should be roughly balanced in workload and sales potential","Territories should be easy to cover with minimal travel time","Territory boundaries should make performance easy to measure","Every territory should get the same revenue target regardless of its potential"],"answer":3,"explanation":"Targets should reflect each territory's potential; identical targets for unequal territories feel unfair and demotivate reps. The other three are standard design aims.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-100","question":"A company sells three very different technical product lines — industrial pumps, lab instruments and software — each needing deep product knowledge. Which sales-force structure fits best?","options":["Product structure","Territorial structure","Customer (market) structure","Pure inside-sales structure"],"answer":0,"explanation":"When products are numerous, complex and unrelated, a product-based sales force lets reps specialise. A territorial structure works best for simple, similar products.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-101","question":"A distributor invests ₹10 lakh in stock and receivables, sells ₹1.2 crore a year at a 5% gross margin and spends ₹3.6 lakh on operating costs. What is its return on investment?","options":["60%","24%","36%","12%"],"answer":1,"explanation":"Gross margin = 5% × 1.2 crore = ₹6 lakh. Net = 6 − 3.6 = ₹2.4 lakh. ROI = 2.4 / 10 = 24%. 60% ignores operating costs.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-102","question":"A distributor sells ₹96 lakh a year at a 4% gross margin on sales. Its inventory turns 12 times a year (measured at cost). What is its gross margin return on inventory investment (GMROI)?","options":["4%","48%","50%","12%"],"answer":2,"explanation":"Gross margin = ₹3.84 lakh; cost of goods = ₹92.16 lakh; average inventory = 92.16 / 12 = ₹7.68 lakh. GMROI = 3.84 / 7.68 = 0.5, or 50%. Fast turns make a thin margin attractive; using sales instead of cost (96/12 = 8) gives 48%.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-103","question":"A media plan reaches 60% of the target audience with an average frequency of 4. What are its gross rating points (GRPs)?","options":["240","64","150","24"],"answer":0,"explanation":"GRP = reach (%) × average frequency = 60 × 4 = 240.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-104","question":"A magazine ad costs ₹4.5 lakh. The magazine has 15 lakh readers, of whom 40% belong to the brand's target group. What is the cost per thousand target readers?","options":["₹300","₹750","₹1,125","₹30"],"answer":1,"explanation":"Target readers = 15,00,000 × 0.40 = 6,00,000. Cost per thousand = 4,50,000 / 600 = ₹750. ₹300 uses all readers rather than the target group.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-105","question":"Why is the percentage-of-sales method of setting the promotion budget often criticised?","options":["It needs data that firms rarely have","It ignores the firm's own costs","It always produces budgets larger than competitors'","It treats sales as the cause of promotion rather than its result, so budgets shrink just when sales need support"],"answer":3,"explanation":"Budgets tied to current sales fall when sales fall — exactly when promotion might be most needed. The objective-and-task method, which costs out the tasks needed to reach set objectives, is considered more logical.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-106","question":"A biscuit company pays retailers an extra allowance for placing its packs on the end-of-aisle display. This is a:","options":["Consumer promotion","Public-relations activity","Trade promotion","Personal-selling activity"],"answer":2,"explanation":"Display and merchandising allowances are aimed at channel members, so they are trade promotions. Consumer promotions (coupons, free samples) target end users.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-107","question":"Assertion (A): Personal selling is usually the most effective promotion tool at the later stages of buying, such as building conviction and closing the sale.\nReason (R): Personal selling allows two-way interaction, so the salesperson can answer objections and adapt the offer on the spot.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Advertising is efficient for awareness, but conviction and action benefit from direct interaction, which is what R describes.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-108","question":"Match each promotion tool with its description.\nA. Advertising  B. Sales promotion  C. Public relations  D. Personal selling\n1. Short-term incentives to encourage purchase\n2. Paid, non-personal presentation by an identified sponsor\n3. Building goodwill and favourable publicity\n4. Face-to-face presentation to make sales and build relationships","options":["A-2, B-3, C-1, D-4","A-1, B-2, C-3, D-4","A-2, B-1, C-4, D-3","A-2, B-1, C-3, D-4"],"answer":3,"explanation":"Advertising is paid non-personal communication, sales promotion gives short-term incentives, PR builds goodwill and personal selling is face to face.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-109","question":"Goods move from manufacturer to wholesaler to retailer to consumer. How many levels does this channel have?","options":["One","Two","Three","Four"],"answer":1,"explanation":"Channel levels are counted by the number of intermediaries: wholesaler and retailer make it a two-level channel.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-110","question":"A firm can sell through a distributor who takes 15% of sales, or build its own sales network costing ₹20 lakh a year fixed plus 5% of sales. Above what annual sales level does the own network become cheaper?","options":["₹1 crore","₹1.33 crore","₹2 crore","₹4 crore"],"answer":2,"explanation":"Indifference point: 0.15S = 20,00,000 + 0.05S → 0.10S = 20 lakh → S = ₹2 crore. Above this, the lower variable cost of the own network outweighs its fixed cost.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-111","question":"A field rep costs ₹9 lakh a year and makes 1,000 calls. One call in ten produces an order; the average order is ₹30,000 at a 20% gross margin. Which statement is correct?","options":["Each call costs ₹900 and generates ₹600 of gross margin, so the calls lose money","Each call costs ₹900 and generates ₹3,000 of gross margin, so the calls are profitable","Each call costs ₹90 and generates ₹600 of gross margin, so the calls are profitable","Each call costs ₹900 and generates ₹6,000 of gross margin, so the calls are profitable"],"answer":0,"explanation":"Cost per call = 9,00,000 / 1,000 = ₹900. Expected margin per call = 0.1 × 30,000 × 0.20 = ₹600. Calls lose ₹300 each, so the firm should raise the hit rate, order size or use cheaper channels (inside sales) for these accounts.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-112","question":"Consider these statements:\nI. A push strategy relies mainly on trade margins, trade promotions and the sales force.\nII. A pull strategy relies mainly on consumer advertising and consumer promotions.\nIII. An FMCG firm should use either push or pull, never both together.\nWhich are correct?","options":["I, II and III","I and II only","I and III only","II only"],"answer":1,"explanation":"I and II are correct. III is false: most FMCG firms combine both, using pull to build demand and push to secure shelf space and availability.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-113","question":"A sales manager sets each rep a target of 60 customer visits and 15 product demonstrations a month. What kind of quota is this?","options":["Activity quota","Profit quota","Sales-volume quota","Expense quota"],"answer":0,"explanation":"Activity quotas target behaviours (calls, demos, new accounts) rather than results. They are useful when the sales cycle is long or results lag effort.","difficulty":"moderate","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-114","question":"Two dealers of the same motorcycle brand in one city keep undercutting each other's prices and poaching each other's customers. This is:","options":["Vertical channel conflict","Channel integration","Multichannel conflict","Horizontal channel conflict"],"answer":3,"explanation":"Horizontal conflict is between members at the same level of the channel. Vertical conflict is between levels, such as dealer versus manufacturer.","difficulty":"hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-115","question":"Consider these statements about media planning:\nI. Gross rating points equal reach multiplied by average frequency.\nII. New brands and complex messages usually need higher frequency.\nIII. Doubling reach will double sales.\nWhich are correct?","options":["I, II and III","I and II only","II and III only","I only"],"answer":1,"explanation":"I and II are correct. III is false: response to advertising shows diminishing returns and depends on message, product and competition, so sales do not rise proportionally with reach.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
  {"id":"mgmt-marketing-116","question":"A sales team has 120 open opportunities with an average deal size of ₹2 lakh, a 25% win rate and an average sales cycle of 60 days. What is its sales velocity (expected revenue per day)?","options":["₹0.25 lakh","₹4 lakh","₹1 lakh","₹60 lakh"],"answer":2,"explanation":"Sales velocity = opportunities × deal size × win rate / cycle length = 120 × 2 × 0.25 / 60 = ₹1 lakh per day. Raising any of the first three or shortening the cycle increases velocity.","difficulty":"very-hard","source":"FMCG MT · Sales management · MBA placement pattern"},
];

export default questions;
